import { getAgentByName } from 'agents';
import { ChannelGateway } from 'agents/experimental/channels';
import { slack } from 'agents/experimental/channels/slack';

// Verifies Slack's signed requests on /webhooks/slack and hands each message
// to the Chat agent of the Slack user who sent it.
export function createSlackGateway(env) {
  return new ChannelGateway({
    channels: {
      slack: slack({
        botToken: env.SLACK_BOT_TOKEN,
        webhook: { signingSecret: env.SLACK_SIGNING_SECRET, path: '/webhooks/slack' },
        // actor.id is "slack:<team>:user:<user>", taken from the verified payload.
        participant: (event) => event.actor?.id ?? null,
      }),
    },
    agent(route) {
      const stub = getAgentByName(env.Chat, route);
      return {
        receive: async (event, origin) => (await stub).receive(event, origin),
        fetch: async (request) => (await stub).fetch(request),
      };
    },
  });
}

// The Slack channel in agents 0.27.0 only handles ingress, so replies go
// straight to the Web API.
export async function postSlackMessage(botToken, surface, text) {
  const address = surface.address;
  const response = await fetch('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      authorization: `Bearer ${botToken}`,
      'content-type': 'application/json; charset=utf-8',
    },
    body: JSON.stringify({
      // A contact surface names a user; Slack opens the DM for a user id.
      channel: address.channelId ?? address.userId,
      ...(address.threadTs && { thread_ts: address.threadTs }),
      text,
    }),
  });
  const result = await response.json().catch(() => ({ ok: false, error: `http_${response.status}` }));
  if (!result.ok) throw new Error(`Slack chat.postMessage failed: ${result.error}`);
}

