import { Agent, routeAgentRequest } from 'agents';
import { createSlackGateway, postSlackMessage } from './slack.js';

export class Chat extends Agent {
  async onMessage(connection, message) {
    connection.send(`echo: ${message}`);
  }

  // Called by the Slack ChannelGateway over RPC with an already verified event.
  async receive(event, origin) {
    if (event.type !== 'message') return;

    // Slack redelivers events it thinks timed out; eventId is stable across retries.
    this.sql`CREATE TABLE IF NOT EXISTS slack_events (id TEXT PRIMARY KEY)`;
    if (this.sql`SELECT id FROM slack_events WHERE id = ${event.eventId}`.length > 0) return;

    const text = event.message.parts
      .filter((part) => part.type === 'text')
      .map((part) => part.text)
      .join('\n')
      .replace(/<@[A-Z0-9]+>\s*/g, '') // drop the bot @mention from app_mention events
      .trim();

    await postSlackMessage(this.env.SLACK_BOT_TOKEN, origin.surface, `echo: ${text}`);
    this.sql`INSERT OR IGNORE INTO slack_events (id) VALUES (${event.eventId})`;
  }
}

export default {
  async fetch(request, env) {
    const slackResponse = await createSlackGateway(env).fetch(request);
    if (slackResponse) return slackResponse;
    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};
